 arch/x86/kvm/irq.c   | 46 +++++++++++++++++++++++++++++++++++++++++---
 2 files changed, 77 insertions(+), 6 deletions(-)

diff --git a/arch/x86/kvm/i8259.c b/arch/x86/kvm/i8259.c
index 6a942ac622d5..20b3b4855974 100644
--- a/arch/x86/kvm/i8259.c
