 {
 	int irq, irq2, intno;
 	struct kvm_pic *s = kvm->arch.vpic;
-
-	s->output = 0;
-
 	pic_lock(s);
+	printk(KERN_WARNING
+           "KVM_DEBUG: pic_read_irq START "
+           "output=%d "
+           "IRR0=%02x IMR0=%02x "
+           "ISR0=%02x\n",
+           s->output,
+           s->pics[0].irr,
+           s->pics[0].imr,
+           s->pics[0].isr);
+	s->output = 0;
+	printk(KERN_WARNING
+           "KVM_DEBUG: output set to 0!\n");
 	irq = pic_get_irq(&s->pics[0]);
+	 printk(KERN_WARNING
+           "KVM_DEBUG: pic_get_irq returned %d\n",
+           irq);
 	if (irq >= 0) {
 		pic_intack(&s->pics[0], irq);
+		printk(KERN_WARNING
+               "KVM_DEBUG: after pic_intack "
+               "IRR0=%02x "
+               "ISR0=%02x "
+               "auto_eoi=%d\n",
+               s->pics[0].irr,
+               s->pics[0].isr,
+               s->pics[0].auto_eoi);
 		if (irq == 2) {
 			irq2 = pic_get_irq(&s->pics[1]);
 			if (irq2 >= 0)
@@ -253,6 +273,9 @@ int kvm_pic_read_irq(struct kvm *kvm)
 		} else
 			intno = s->pics[0].irq_base + irq;
 	} else {
+		 printk(KERN_WARNING
+               "KVM_DEBUG: spurious IRQ! "
+               "no irq found in IRR!\n");
 		/*
 		 * spurious IRQ on host controller
 		 */
@@ -260,6 +283,14 @@ int kvm_pic_read_irq(struct kvm *kvm)
 		intno = s->pics[0].irq_base + irq;
 	}
 	pic_update_irq(s);
+	 printk(KERN_WARNING
+           "KVM_DEBUG: pic_read_irq END "
+           "intno=%d "
+           "output=%d "
+           "IRR0=%02x\n",
+           intno,
+           s->output,
+           s->pics[0].irr);
 	pic_unlock(s);
 
 	return intno;
diff --git a/arch/x86/kvm/irq.c b/arch/x86/kvm/irq.c
index 8c62c6d4d5c1..0dad5d3c5413 100644
--- a/arch/x86/kvm/irq.c
+++ b/arch/x86/kvm/irq.c
@@ -79,8 +79,19 @@ int kvm_cpu_has_extint(struct kvm_vcpu *v)
