 #ifdef CONFIG_KVM_IOAPIC
-	if (pic_in_kernel(v->kvm))
+	if (pic_in_kernel(v->kvm)) {
+		 printk(KERN_WARNING
+               "KVM_DEBUG: has_extint called "
+               "output=%d "
+               "IRR0=%02x IRR1=%02x "
+               "IMR0=%02x IMR1=%02x\n",
+               v->kvm->arch.vpic->output,
+               v->kvm->arch.vpic->pics[0].irr,
+               v->kvm->arch.vpic->pics[1].irr,
